const rawValue = $json.text;

let rawText = "";

if (typeof rawValue === "string") {
  rawText = rawValue;
} else if (rawValue !== undefined && rawValue !== null) {
  try {
    rawText = JSON.stringify(rawValue);
  } catch {
    rawText = String(rawValue);
  }
}

// Retrieve the original lead data
let lead = {};
let leadReadError = "";

try {
  const originalLead = $("Edit Fields - Clean Data").item.json;

  if (
    originalLead &&
    typeof originalLead === "object" &&
    !Array.isArray(originalLead)
  ) {
    lead = originalLead;
  } else {
    leadReadError = "Original lead data is unavailable.";
  }
} catch (error) {
  leadReadError = error.message || "Could not read original lead data.";
}

// Extract the first complete JSON object
function extractFirstJsonObject(text) {
  const startIndex = text.indexOf("{");

  if (startIndex === -1) {
    return null;
  }

  let depth = 0;
  let insideString = false;
  let escaped = false;

  for (let i = startIndex; i < text.length; i++) {
    const char = text[i];

    if (insideString) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === '"') {
        insideString = false;
      }

      continue;
    }

    if (char === '"') {
      insideString = true;
    } else if (char === "{") {
      depth++;
    } else if (char === "}") {
      depth--;

      if (depth === 0) {
        return text.slice(startIndex, i + 1);
      }
    }
  }

  return null;
}

try {
  if (leadReadError) {
    throw new Error(leadReadError);
  }

  if (!rawText.trim()) {
    throw new Error("AI output is missing or empty.");
  }

  // Remove Markdown code fences if present
  let cleanedText = rawText.trim();

  cleanedText = cleanedText
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  let parsed;

  // First attempt: parse the complete response
  try {
    parsed = JSON.parse(cleanedText);
  } catch {
    // Second attempt: extract the first JSON object
    const jsonBlock = extractFirstJsonObject(cleanedText);

    if (!jsonBlock) {
      throw new Error("No JSON object found in AI output.");
    }

    parsed = JSON.parse(jsonBlock);
  }

  // Validate that the result is a JSON object
  if (
    !parsed ||
    typeof parsed !== "object" ||
    Array.isArray(parsed)
  ) {
    throw new Error("AI output must be a JSON object.");
  }

  // Validate summary
  const summary =
    typeof parsed.summary === "string"
      ? parsed.summary.trim()
      : "";

  // Validate and normalize score
  const rawScore = parsed.score;

  const score =
    (typeof rawScore === "number" ||
      (typeof rawScore === "string" &&
        rawScore.trim() !== ""))
      ? Number(rawScore)
      : NaN;

  // Validate and normalize category
  const category =
    typeof parsed.category === "string"
      ? parsed.category.trim().toLowerCase()
      : "";

  // Validate reason
  const reason =
    typeof parsed.reason === "string"
      ? parsed.reason.trim()
      : "";

  if (!summary) {
    throw new Error("Summary is missing or invalid.");
  }

  if (!Number.isInteger(score) || score < 1 || score > 10) {
    throw new Error("Score must be an integer from 1 to 10.");
  }

  if (!["hot", "warm", "cold"].includes(category)) {
    throw new Error("Category must be hot, warm, or cold.");
  }

  if (!reason) {
    throw new Error("Reason is missing or invalid.");
  }

  // Successful result
  return {
    json: {
      ...lead,
      ai_status: "ok",
      summary,
      score,
      category,
      reason
    }
  };

} catch (error) {

  // Never stop the workflow because of invalid AI output
  return {
    json: {
      ...lead,
      ai_status: "needs_review",
      ai_raw: rawText.slice(0, 1000),
      ai_error: error.message || "Unknown AI parsing error."
    }
  };
}

