parameters.jsCode:
const lead = $("Save AI Result").first().json;
const draft = $("AI - Follow-up Email Draft").first().json.text;

if (!lead.email) {
  throw new Error("Lead email address is missing.");
}

if (typeof draft !== "string" || !draft.trim()) {
  throw new Error("Email draft is missing.");
}

const subjectMatch = draft.match(/^Subject:\s*(.+)$/im);
const bodyMatch = draft.match(/^Body:\s*([\s\S]*)$/im);

if (!subjectMatch || !bodyMatch || !bodyMatch[1].trim()) {
  throw new Error("Could not extract email subject and body.");
}

return {
  json: {
    to: lead.email,
    subject: subjectMatch[1].trim(),
    body: bodyMatch[1].trim(),
    lead_id: lead.id
  }
};
